from taf.sw.dcap.rd.services.custom_traces.custom_base import CustomTraceBase
from taf.sw.dcap.rd.services.custom_traces.bts_custom_profile import CustomBTSTraceProfile
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.trace_profile_tracer import TraceProfileTracer
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.provided_trace import ProvidedTrace

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CustomVduTraceProfile(CustomTraceBase):
    def __init__(self, requirements, **kwargs):
        super(CustomVduTraceProfile, self).__init__()

        self.custom_trace_profile = self._generate_custom_trace_profile(requirements=requirements,
                                                                        trace_type="VDU",
                                                                        **kwargs)

    def get_l2_5g(self, included_trace_mode, **kwargs):
        provided_traces = []
        provided_traces += [ProvidedTrace(
            snapshot=False,
            trace="l2Vdu")]
        return [TraceProfileTracer(
            provided_traces=provided_traces,
            params=[
                {
                    "values": included_trace_mode,
                    "name": "l2TraceMode"
                }
            ], type='VDU',
            name="L2", id="l2Vdu")]

    @staticmethod
    def custom_vdu_l1_stream(custom_vdu_dict, **kwargs):
        vdu_custom_profile = "L1StreamVdu"
        l1_trace_vdu = kwargs.get('l1_trace_vdu', ['ID 10: Syscom: all Syscom message, no subtype'])
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_vdu_dict[vdu_custom_profile].get('tracer_id'),
                type="VDU")],
            params=CustomTraceBase.custom_l1_stream(l1_trace_vdu, "Streaming"),
            type="VDU",
            name=custom_vdu_dict[vdu_custom_profile].get('name'),
            id=custom_vdu_dict[vdu_custom_profile].get('tracer_id'))

    @staticmethod
    def custom_vdu_tss(custom_vdu_dict, bts_Id=None, script_names=None, cells=None,
                       bbmods=None, rmods=None, free_text_parameters=None, **kwargs):
        vdu_custom_profile = "tssVdu"
        if bts_Id and ":" not in bts_Id:
            bts_Id += ":443"
        formatted_values = CustomBTSTraceProfile.format_tss_values(script_names, cells, bbmods, rmods,
                                                                   free_text_parameters)
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_vdu_dict[vdu_custom_profile].get('tracer_id'),
                type='VDU')],
            params=[
                {
                    "name": bts_Id,
                    "values": formatted_values
                }], type='VDU',
            name=custom_vdu_dict[vdu_custom_profile].get('name'),
            id=custom_vdu_dict[vdu_custom_profile].get('tracer_id'))

    @staticmethod
    def custom_vdu_syslog(custom_vdu_dict, **kwargs):
        vdu_custom_profile = 'syslogVdu'
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_vdu_dict[vdu_custom_profile].get('tracer_id'),
                type='VDU')],
            params=CustomTraceBase.custom_syslog_vran(kwargs),
            type='VDU',
            name=custom_vdu_dict[vdu_custom_profile].get('name'),
            id=custom_vdu_dict[vdu_custom_profile].get('tracer_id'))

    @staticmethod
    def custom_vdu_control_plane_interface(custom_vdu_dict, **kwargs):
        vdu_custom_profile = "controlPlane5gVdu"
        control_plane_interface = kwargs.get('vdu_control_plane_interface', 'auto')
        monitoring_profiles = kwargs.get('vdu_monitoring_profiles', 'vdu-full-call-scenarios')
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_vdu_dict[vdu_custom_profile].get('tracer_id'),
                type="VDU")],
            params=CustomTraceBase.custom_control_plane_interface(control_plane_interface=control_plane_interface,
                                                                  monitoring_profiles=monitoring_profiles),
            type="VDU",
            name=custom_vdu_dict[vdu_custom_profile].get('name'),
            id=custom_vdu_dict[vdu_custom_profile].get('tracer_id'))

    @staticmethod
    def custom_vdu_l1iq(custom_vdu_dict, **kwargs):
        l1iq_direction = kwargs.get('l1Iq_direction', 'UL')
        vdu_custom_profile = 'l1IqVdu'
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_vdu_dict[vdu_custom_profile].get('tracer_id'),
                type='VDU')],
            params=CustomTraceBase.custom_l1iq_vdu(l1iq_direction),
            type='VDU',
            name=custom_vdu_dict[vdu_custom_profile].get('name'),
            id=custom_vdu_dict[vdu_custom_profile].get('tracer_id'))

    @staticmethod
    def custom_event_based_tracer_vdu(custom_vdu_dict, **kwargs):
        vdu_custom_profile = 'eventBasedTracerVdu'
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_vdu_dict[vdu_custom_profile].get('tracer_id'),
                type='VDU')],
            params=[],
            type='VDU',
            name=custom_vdu_dict[vdu_custom_profile].get('name'),
            id=custom_vdu_dict[vdu_custom_profile].get('tracer_id'))

    @staticmethod
    def custom_vdu_screl(custom_vdu_dict, **kwargs):
        vdu_custom_profile = "screlVdu"
        kwargs['screl_coverage_vdu'] = kwargs.get('screl_coverage_vdu') or "default"
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_vdu_dict[vdu_custom_profile].get('tracer_id'),
                type="VDU")],
            params=[
                {
                    "name": "screlCoverage",
                    "values": [
                        kwargs['screl_coverage_vdu']
                    ]
                }], type="VDU",
            name=custom_vdu_dict[vdu_custom_profile].get('name'),
            id=custom_vdu_dict[vdu_custom_profile].get('tracer_id'))

    def custom_tracers(self, custom_profile, trace_type, **kwargs):
        if custom_profile == 'flowTracerVdu':
            logger.warning("flowTracerVdu is deprecated, please use controlPlane5gVdu instead.")
        custom_vdu_dict = {'snapshotVdu': {'name': 'Snapshot', 'tracer_id': 'snapshotVdu'},
                           'tracerVdu': {'name': 'Cell Trace', 'tracer_id': 'ntracerVdu'},
                           'flowTracerVdu': {'name': 'Control Plane', 'tracer_id': 'flowTracerVdu'},
                           'tssVdu': {'tracer_id': 'tssVdu', 'name': 'Troubleshooting scripts'},
                           'L1StreamVdu': {'tracer_id': 'l1Vdu', 'name': 'L1 Stream'},
                           'controlPlane5gVdu': {'tracer_id': 'controlPlane5gVdu', 'name': 'Control Plane'},
                           'syslogVdu': {'name': 'Syslog', 'tracer_id': 'syslogVdu'},
                           'l1IqVdu': {'name': 'L1-IQ', 'tracer_id': 'l1iqVdu'},
                           'eventBasedTracerVdu': {'name': 'Event-Based L1-IQ', 'tracer_id': 'eventBasedTracerVdu'},
                           'screlVdu': {'name': 'System critical event logs (SCREL)', 'tracer_id': 'screlVdu'}}

        profile_functions = {
            'tssVdu': self.custom_vdu_tss,
            'L1StreamVdu': self.custom_vdu_l1_stream,
            'syslogVdu': self.custom_vdu_syslog,
            'controlPlane5gVdu': self.custom_vdu_control_plane_interface,
            'l1IqVdu': self.custom_vdu_l1iq,
            'eventBasedTracerVdu': self.custom_event_based_tracer_vdu,
            'screlVdu': self.custom_vdu_screl
        }

        custom_vdu_profile_option = []

        if custom_profile in profile_functions:
            custom_vdu_profile_option.append(profile_functions[custom_profile](
                custom_vdu_dict=custom_vdu_dict,
                **kwargs))
        elif custom_profile in custom_vdu_dict:
            custom_vdu_profile_option.append(TraceProfileTracer(
                provided_traces=[ProvidedTrace(
                    snapshot=False,
                    trace=custom_vdu_dict[custom_profile].get('tracer_id'),
                    type=trace_type)],
                params=[], type=trace_type,
                name=custom_vdu_dict[custom_profile].get('name'),
                id=custom_vdu_dict[custom_profile].get('tracer_id')))
        return custom_vdu_profile_option
